defmodule Mix.Lumina.Fixtures do
  @moduledoc """
  Barry-generated test fixtures and their metadata.

  Each fixture is a folder `test/fixtures/barry/<id>/` holding:

    * `case.repo` - the Barry Repository Descriptor
    * `case.exs` - the metadata, a literal map (see below)
    * `case.tal`, `rsync/`, `rrdp/` - Barry's output, generated by
      `mix lumina.fixtures.gen` and committed

  The metadata documents why the fixture exists and what a correct validator
  must conclude from it:

      %{
        id: "m4-ca-cert-expired",
        title: "CA certificate past its notAfter date",
        milestone: "M4",
        rationale: \"""
        Why this test exists and which mistake it catches.
        \""",
        rfc: ["5280#6.1.3", "6487#4.6"],
        expected: {:invalid, [%{object: "ta/ca1.cer", reason: "expired"}]},
        barry: [now: "2020-01-01T00:00:00Z", later: "2021-01-01T00:00:00Z"]
      }

  `expected` is `:valid`, or `{:invalid, rejects}` where each reject names an
  object (a path under `rsync/`) and the reason it must be rejected. `barry`
  is optional and overrides the default validity period.

  `case.exs` is read as data: anything but literal values (maps, lists,
  tuples, strings, atoms, numbers) is rejected, and nothing in it is run.
  See `doc/testing.md`.
  """

  alias Mix.Lumina.RFC

  @default_dir "test/fixtures/barry"

  @doc "Default validity period passed to Barry (`--now`, `--later`)."
  def default_barry_opts, do: [now: "2026-01-01T00:00:00Z", later: "2036-01-01T00:00:00Z"]

  @required [:id, :title, :milestone, :rationale, :rfc, :expected]
  @optional [:barry]
  @milestones Enum.map(0..9, &"M#{&1}")
  @id_regex ~r/\Am[0-9]-[a-z0-9]+(?:-[a-z0-9]+)*\z/

  @type fixture :: %{
          required(:id) => String.t(),
          required(:title) => String.t(),
          required(:milestone) => String.t(),
          required(:rationale) => String.t(),
          required(:rfc) => [String.t()],
          required(:expected) => :valid | {:invalid, [%{object: String.t(), reason: String.t()}]},
          required(:dir) => Path.t(),
          optional(:barry) => keyword(String.t())
        }
  @type problem :: %{file: Path.t(), message: String.t()}

  @doc "The fixture root directory."
  @spec dir() :: Path.t()
  def dir, do: @default_dir

  @doc """
  Loads every fixture under `dir` and checks it. Returns the fixtures that
  passed and the problems found.
  """
  @spec load_all(Path.t(), RFC.library()) :: {[fixture()], [problem()]}
  def load_all(dir \\ @default_dir, library \\ RFC.load_library()) do
    dir
    |> case_dirs()
    |> Enum.map(&load(&1, library))
    |> Enum.reduce({[], []}, fn
      {:ok, fixture}, {fixtures, problems} -> {fixtures ++ [fixture], problems}
      {:error, found}, {fixtures, problems} -> {fixtures, problems ++ found}
    end)
  end

  @doc "Lists the fixture folders under `dir`, sorted."
  @spec case_dirs(Path.t()) :: [Path.t()]
  def case_dirs(dir \\ @default_dir) do
    dir
    |> Path.join("*")
    |> Path.wildcard()
    |> Enum.filter(&File.dir?/1)
    |> Enum.sort()
  end

  @doc """
  Loads one fixture folder and checks its metadata and generated output.
  """
  @spec load(Path.t(), RFC.library()) :: {:ok, fixture()} | {:error, [problem()]}
  def load(case_dir, library \\ RFC.load_library()) do
    with {:ok, meta} <- read_metadata(case_dir) do
      problems =
        check_files(case_dir, :descriptor) ++
          check_metadata(meta, case_dir, library) ++
          check_files(case_dir, :output) ++
          check_rejects(meta, case_dir)

      case problems do
        [] -> {:ok, Map.put(meta, :dir, case_dir)}
        messages -> {:error, Enum.map(messages, &%{file: meta_path(case_dir), message: &1})}
      end
    else
      {:error, message} -> {:error, [%{file: meta_path(case_dir), message: message}]}
    end
  end

  @doc """
  Reads `case.exs` as data. Only literal values are accepted.
  """
  @spec read_metadata(Path.t()) :: {:ok, map()} | {:error, String.t()}
  def read_metadata(case_dir) do
    path = meta_path(case_dir)

    with {:ok, source} <- read(path),
         {:ok, ast} <- quote_source(source, path),
         {:ok, term} <- literal(ast) do
      if is_map(term), do: {:ok, term}, else: {:error, "metadata must be a map"}
    end
  end

  @doc "Path of a fixture's metadata file."
  @spec meta_path(Path.t()) :: Path.t()
  def meta_path(case_dir), do: Path.join(case_dir, "case.exs")

  @doc "Barry options for a fixture: the defaults merged with its `:barry` overrides."
  @spec barry_opts(map()) :: keyword(String.t())
  def barry_opts(meta), do: Keyword.merge(default_barry_opts(), Map.get(meta, :barry, []))

  defp read(path) do
    case File.read(path) do
      {:ok, source} -> {:ok, source}
      {:error, :enoent} -> {:error, "missing case.exs"}
      {:error, reason} -> {:error, "cannot read case.exs: #{:file.format_error(reason)}"}
    end
  end

  defp quote_source(source, path) do
    case Code.string_to_quoted(source, file: path) do
      {:ok, ast} -> {:ok, ast}
      {:error, {_meta, message, token}} -> {:error, "cannot parse case.exs: #{message}#{token}"}
    end
  end

  # Converts the AST of a literal into a term, without evaluating anything.
  defp literal(value) when is_binary(value) or is_atom(value) or is_number(value),
    do: {:ok, value}

  defp literal(list) when is_list(list), do: literal_list(list)

  defp literal({left, right}) do
    with {:ok, [l, r]} <- literal_list([left, right]), do: {:ok, {l, r}}
  end

  defp literal({:{}, _, elements}) do
    with {:ok, terms} <- literal_list(elements), do: {:ok, List.to_tuple(terms)}
  end

  defp literal({:%{}, _, pairs}) do
    with {:ok, terms} <- literal_list(pairs), do: {:ok, Map.new(terms)}
  end

  defp literal({:__block__, _, [single]}), do: literal(single)

  defp literal(other) do
    {:error, "case.exs must contain only literal values, found: #{Macro.to_string(other)}"}
  end

  defp literal_list(list) do
    Enum.reduce_while(list, {:ok, []}, fn ast, {:ok, acc} ->
      case literal(ast) do
        {:ok, term} -> {:cont, {:ok, acc ++ [term]}}
        error -> {:halt, error}
      end
    end)
  end

  defp check_metadata(meta, case_dir, library) do
    id = Path.basename(case_dir)

    missing =
      for key <- @required, not Map.has_key?(meta, key), do: "missing required key :#{key}"

    unknown =
      for key <- Map.keys(meta),
          key not in (@required ++ @optional),
          do: "unknown key #{inspect(key)}"

    missing ++
      unknown ++
      check(meta, :id, fn
        ^id ->
          if Regex.match?(@id_regex, id),
            do: [],
            else: [
              "id #{inspect(id)} must look like \"m4-short-description\" (lowercase, hyphens)"
            ]

        other ->
          ["id #{inspect(other)} must match the folder name #{inspect(id)}"]
      end) ++
      check(meta, :title, &non_blank(&1, :title)) ++
      check(meta, :rationale, &non_blank(&1, :rationale)) ++
      check(meta, :milestone, fn
        milestone when milestone in @milestones ->
          if String.starts_with?(id, String.downcase(milestone) <> "-"),
            do: [],
            else: ["id #{inspect(id)} must start with \"#{String.downcase(milestone)}-\""]

        other ->
          ["milestone must be one of M0..M9, got: #{inspect(other)}"]
      end) ++
      check(meta, :rfc, fn
        [_ | _] = refs ->
          for ref <- refs,
              {:error, message} <- [RFC.validate(ref, library)],
              do: "rfc: #{message}"

        _ ->
          ["rfc must be a non-empty list of RFC references such as \"6487#4.8.9\""]
      end) ++
      check(meta, :expected, &check_expected/1) ++
      check(meta, :barry, &check_barry/1)
  end

  defp check(meta, key, fun) do
    case Map.fetch(meta, key) do
      {:ok, value} -> fun.(value)
      :error -> []
    end
  end

  defp non_blank(value, key) do
    if is_binary(value) and String.trim(value) != "",
      do: [],
      else: ["#{key} must be a non-blank string"]
  end

  defp check_expected(:valid), do: []

  defp check_expected({:invalid, [_ | _] = rejects}) do
    rejects
    |> Enum.with_index(1)
    |> Enum.flat_map(fn
      {%{object: object, reason: reason} = reject, n} when map_size(reject) == 2 ->
        cond do
          not is_binary(object) or String.trim(object) == "" ->
            ["expected reject #{n}: object must be a path under rsync/"]

          not is_binary(reason) or String.trim(reason) == "" ->
            ["expected reject #{n}: reason must be a non-blank string"]

          true ->
            []
        end

      {other, n} ->
        ["expected reject #{n} must be %{object: ..., reason: ...}, got: #{inspect(other)}"]
    end)
  end

  defp check_expected(other) do
    [
      "expected must be :valid or {:invalid, [%{object: ..., reason: ...}, ...]}, got: #{inspect(other)}"
    ]
  end

  defp check_barry(opts) do
    if Keyword.keyword?(opts) do
      Enum.flat_map(opts, fn
        {key, value} when key in [:now, :later] ->
          case DateTime.from_iso8601(to_string(value)) do
            {:ok, _, 0} when is_binary(value) ->
              []

            _ ->
              ["barry #{key}: must be a UTC timestamp such as \"2026-01-01T00:00:00Z\""]
          end

        {key, _} ->
          ["barry: unknown option #{inspect(key)} (allowed: :now, :later)"]
      end)
    else
      ["barry must be a keyword list, got: #{inspect(opts)}"]
    end
  end

  defp check_files(case_dir, :descriptor) do
    if File.regular?(Path.join(case_dir, "case.repo")), do: [], else: ["missing case.repo"]
  end

  defp check_files(case_dir, :output) do
    tal = if File.regular?(Path.join(case_dir, "case.tal")), do: [], else: ["missing case.tal"]

    rsync =
      if Path.wildcard(Path.join([case_dir, "rsync", "**", "*"])) |> Enum.any?(&File.regular?/1),
        do: [],
        else: ["missing generated rsync/ tree"]

    case tal ++ rsync do
      [] -> []
      found -> found ++ ["run `mix lumina.fixtures.gen #{Path.basename(case_dir)}`"]
    end
  end

  defp check_rejects(%{expected: {:invalid, rejects}}, case_dir) when is_list(rejects) do
    for %{object: object} when is_binary(object) <- rejects,
        not File.regular?(Path.join([case_dir, "rsync", object])),
        do: "expected reject object #{inspect(object)} is not in rsync/"
  end

  defp check_rejects(_meta, _case_dir), do: []
end
